<script setup>
import {ref,computed,watch,nextTick,onUnmounted} from 'vue';
import RichText from './RichText.vue';import ChatAttachment from './ChatAttachment.vue';import {readEvents} from '../chatStream.js';
const props=defineProps({catalog:Object,token:String,api:Function});const emit=defineEmits(['refresh','session','memory','specification']);
const sid=ref(null),messages=ref([]),prompt=ref(''),busy=ref(false),status=ref(''),error=ref(''),files=ref([]),imageMode=ref(false),input=ref(null),bottom=ref(null),chosen=ref([]);let abort;
const originals=ref({});
function displayText(message){let text=message.content;for(const [index,c] of (message.citations||[]).entries())if(c.chunk_id)text=text.replaceAll('['+c.chunk_id+']','['+(index+1)+']');return text;}
async function original(id){try{originals.value[id]=(await props.api('/contexts/'+id+'/original')).url;}catch(e){error.value=e.message;}}
const board=computed(()=>props.catalog.board[0]);const experts=computed(()=>props.catalog.expert.filter(e=>board.value?.expert_ids.includes(e.id)&&e.primary_source_ids?.length));const sessions=computed(()=>props.catalog.session.filter(s=>s.session_kind!=='library').slice().reverse());
watch(experts,value=>{if(!sid.value)chosen.value=value.map(e=>e.id)},{immediate:true});
async function scroll(){await nextTick();bottom.value?.scrollIntoView({behavior:'smooth',block:'nearest'});}
async function open(id){if(busy.value)return;error.value='';sid.value=id;if(!id)chosen.value=experts.value.map(e=>e.id);messages.value=id?await props.api('/sessions/'+id+'/messages'):[];files.value=[];emit('session',id);await scroll();}
function select(event){for(const file of Array.from(event.target.files||event.clipboardData?.files||event.dataTransfer?.files||[])){if(!/\.(pdf|txt|md|png|jpe?g|webp)$/i.test(file.name)){error.value='Use PDF, texto, Markdown, PNG, JPG o WebP.';continue;}if(file.type.startsWith('image/')&&file.size>16*1024*1024){error.value='Para analizar imágenes, use archivos de hasta 16 MB.';continue;}if(files.value.length>=12){error.value='Puede adjuntar hasta 12 archivos por mensaje.';break;}files.value.push({file,id:null,uploaded:false});}if(event.target===input.value)input.value.value='';}
async function ensureSession(){if(sid.value)return;const s=await props.api('/sessions',{board_id:board.value.id,title:(prompt.value||'Conversación con el consejo').slice(0,100),expert_ids:chosen.value});sid.value=s.id;emit('session',s.id);emit('refresh');}
async function upload(entry){if(!entry.id){const d=await props.api('/contexts',{session_id:sid.value,title:entry.file.name,text:'',scope:'SESSION',retention_hours:24,permanent_consent:false,expert_ids:[]});entry.id=d.id;}
 if(!entry.uploaded){const mime=entry.file.type||(/\.pdf$/i.test(entry.file.name)?'application/pdf':/\.md$/i.test(entry.file.name)?'text/markdown':'text/plain');const upload=await props.api('/sessions/'+sid.value+'/attachments/'+entry.id+'/upload?content_type='+encodeURIComponent(mime),{});const form=new FormData();Object.entries(upload.fields).forEach(([key,value])=>form.append(key,value));form.append('file',entry.file);const r=await fetch(upload.url,{method:'POST',body:form,signal:abort.signal});if(!r.ok)throw Error('La carga falló. Puede reintentar.');await props.api('/contexts/'+entry.id+'/finalize',{});entry.uploaded=true;}
 const deadline=Date.now()+60*60*1000;while(true){if(Date.now()>deadline)throw Error('El adjunto sigue pendiente. Puede reintentar cuando termine de prepararse.');if(abort.signal.aborted)throw new DOMException('Stopped','AbortError');const catalog=await props.api('/catalog');const doc=catalog.context.find(d=>d.id===entry.id);if(!doc)throw Error('El adjunto dejó de estar disponible');if(doc.status==='ready')return entry.id;if(doc.status==='failed')throw Error('No se pudo preparar '+entry.file.name+'. Retire el archivo y vuelva a intentarlo.');status.value='Preparando '+entry.file.name+'…';await new Promise(resolve=>setTimeout(resolve,1800));}}
async function send(){if(busy.value||(!prompt.value.trim()&&!files.value.length))return;busy.value=true;error.value='';abort=new AbortController();try{await ensureSession();if(imageMode.value){status.value='Creando imagen…';messages.value=await props.api('/sessions/'+sid.value+'/images',{prompt:prompt.value});}else{const ids=[];for(const entry of files.value)ids.push(await upload(entry));status.value='El consejo consulta las fuentes y revisa sus respuestas…';const text=prompt.value.trim()||'Analice los archivos adjuntos en el contexto de esta conversación.';const response=await fetch('/api/sessions/'+sid.value+'/turns/stream',{method:'POST',headers:{Authorization:'Bearer '+props.token,'Content-Type':'application/json'},body:JSON.stringify({text,attachment_ids:ids}),signal:abort.signal});await readEvents(response,(event,data)=>{if(event==='messages'){messages.value=data;scroll();}if(event==='error')throw Error(data.message);});}prompt.value='';files.value=[];emit('refresh');await scroll();}catch(e){if(e.name!=='AbortError')error.value=e.message;if(sid.value)messages.value=await props.api('/sessions/'+sid.value+'/messages').catch(()=>messages.value);}finally{busy.value=false;status.value='';}}
function stop(){abort?.abort();}onUnmounted(stop);
async function copy(text){try{await navigator.clipboard.writeText(text);}catch{error.value='No se pudo copiar el mensaje.';}}
</script>
<template><div class="council-chat"><div class="chat-toolbar"><button @click="open(null)" :disabled="busy">＋ Nueva conversación</button><select aria-label="Historial de conversaciones" :value="sid||''" @change="open($event.target.value||null)" :disabled="busy"><option value="">Historial de conversaciones</option><option v-for="s in sessions" :key="s.id" :value="s.id">{{s.title}}</option></select><button v-if="sid" @click="emit('memory',sid)" :disabled="busy">Memoria</button><button v-if="sid" @click="emit('specification',sid)" :disabled="busy">Especificaciones</button></div>
<div v-if="!messages.length" class="chat-welcome"><p class="eyebrow">SU CONSEJO, EN UNA CONVERSACIÓN</p><h2>¿Qué quiere explorar?</h2><p>Contraste ideas con perspectivas sustentadas en los libros que habilitó.</p><div class="chat-experts"><label v-for="e in experts" :key="e.id"><input v-model="chosen" type="checkbox" :value="e.id" :disabled="!!sid||busy"/> {{e.name}}</label></div><p class="muted">Analistas virtuales inspirados en sus obras. Puede revisar las citas en cada intervención.</p><button class="starter" @click="prompt='Quiero diseñar un agente. Antes de proponer una solución, ayúdenme a aclarar el problema y contrastar alternativas con citas de sus libros.'">Ayúdenme a diseñar un agente →</button></div>
<div class="chat-messages" aria-live="polite"><article v-for="m in messages" :key="m.id" class="chat-message" :class="{'owner-message':m.speaker==='Propietario'}"><div class="message-heading"><strong>{{m.speaker==='Propietario'?'Usted':m.speaker}}</strong><button @click="copy(m.content)" aria-label="Copiar mensaje">Copiar</button></div><RichText :text="displayText(m)"/><ChatAttachment v-for="a in m.attachments" :key="a.id" :attachment="a" :session="sid" :token="token"/><details v-if="m.citations?.length" class="chat-citations"><summary>{{m.citations.length}} citas · revisar evidencia</summary><div v-for="(c,index) in m.citations" :key="index"><strong>{{c.source_title||c.title||'Fuente documental'}}{{c.page?' · página '+c.page:''}}</strong><blockquote>{{c.quote}}</blockquote><small>{{c.source?.author||c.author||c.source_author}} · {{c.verification==='quote_match_and_model_review'?'Cita cotejada y revisada por modelo':'Sin verificación completa'}}</small><div v-if="c.has_original"><button v-if="!originals[c.document_id]" @click="original(c.document_id)">Consultar original</button><a v-else :href="originals[c.document_id]" target="_blank" rel="noopener noreferrer">Abrir documento original ↗</a></div></div></details></article><p v-if="busy" class="chat-status" role="status">{{status}}</p><div ref="bottom"/></div>
<p v-if="error" class="chat-error" role="alert">{{error}}</p><form class="chat-composer" @submit.prevent="send" @dragover.prevent @drop.prevent="select" @paste="select"><div class="pending-files"><span v-for="(entry,index) in files" :key="index">{{entry.file.name}}<button type="button" @click="files.splice(index,1)" :disabled="busy" aria-label="Retirar archivo">×</button></span></div><textarea v-model="prompt" :placeholder="imageMode?'Describa la imagen que quiere crear…':'Converse con el consejo…'" aria-label="Mensaje al consejo" rows="3" :disabled="busy" @keydown.enter.exact.prevent="send"/><div class="composer-actions"><label v-if="!imageMode" class="attach-button">＋ Adjuntar<input ref="input" type="file" multiple accept=".pdf,.txt,.md,.png,.jpg,.jpeg,.webp" @change="select" :disabled="busy"/></label><label><input type="checkbox" v-model="imageMode" :disabled="busy||!!files.length"/> Crear imagen</label><button v-if="busy&&!imageMode" type="button" @click="stop">Detener</button><button type="submit" class="send-button" :disabled="busy||(!prompt.trim()&&!files.length)||(!sid&&!chosen.length)">{{imageMode?'Crear imagen':'Enviar ↑'}}</button></div></form><p class="chat-footnote">{{imageMode?'Las imágenes generadas usan sus créditos de OpenRouter y son ilustraciones, no evidencia.':'Adjuntos temporales: 24 horas. Se procesan en su servidor y, para su análisis, mediante OpenRouter.'}} Las respuestas pueden contener errores; revise las fuentes.</p></div></template>
